#include <algorithm>
#include <cassert>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <vector>
#include "sm121_integer_core.h"
using qrt_q1_moe_hawkeye::Value;
using qrt_sm121_integer_core::Row;
std::vector<uint16_t> read(const char* path,size_t words) {
    std::ifstream f(path,std::ios::binary|std::ios::ate);assert(f&&size_t(f.tellg())==words*2u);
    std::vector<uint16_t> values(words);f.seekg(0);assert(bool(f.read(reinterpret_cast<char*>(values.data()),words*2u)));return values;
}
unsigned seed=0x39520269u;
unsigned random_word(){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;}
uint32_t bits(float f){uint32_t v;std::memcpy(&v,&f,4u);return v;}
int main(int argc,char** argv) {
    assert(argc==3);const auto q=read(argv[1],7169u*4096u),k=read(argv[2],7169u*512u);
    unsigned long long shift_hist[97]{},exceptions[17]{},groups=0u,unsupported=0u,packed=0u,loss_pairs=0u,exception_pairs=0u,no_correction=0u,bounds_mismatches=0u;
    for(unsigned sample=0u;sample<65536u;++sample) {
        const unsigned query=random_word()%7169u,key=random_word()%(query+1u),head=random_word()%16u;
        const auto* qrow=q.data()+(size_t(query)*16u+head)*256u;
        const auto* krow=k.data()+(size_t(key)*2u+head/8u)*256u;
        Value carry{0u,-133,false};
        for(unsigned base=0u;base<256u;base+=16u) {
            Row a{},b{};Value terms[17];terms[0]=carry;
            for(unsigned i=0u;i<16u;++i){a.original[i]=qrow[base+i];b.original[i]=krow[base+i];terms[i+1u]=qrt_q1_moe_hawkeye::multiply_bf16(a.original[i],b.original[i],-133);}
            qrt_sm121_integer_core::prepare(a);qrt_sm121_integer_core::prepare(b);++groups;
            if(a.unit<0||b.unit<0)++unsupported;
            else {
                int maximum=carry.exponent>-133?carry.exponent:-133;
                if(a.maximum+b.maximum-254>maximum)maximum=qrt_sm121_integer_core::paired_maximum(a,b,maximum);
                const int shift=maximum-(a.unit+b.unit-254)-11;assert(shift>=-32&&shift<=64);++shift_hist[shift+32];
                const unsigned exceptional=(a.exceptions|b.exceptions)&a.nonzero&b.nonzero;
                const unsigned loss=shift>0?qrt_sm121_integer_core::remainder_mask(a,b,unsigned(shift)):0u;
                ++exceptions[__builtin_popcount(exceptional)];exception_pairs+=__builtin_popcount(exceptional);loss_pairs+=__builtin_popcount(loss);no_correction+=!(loss|exceptional);
                if(shift>=-25&&shift<=16) {
                    ++packed;int64_t mathematical=0,remainder=0,corrections=0,reference=0;
                    const unsigned mask=shift>0?(1u<<shift)-1u:0u;
                    for(unsigned pair=0u;pair<8u;++pair) {
                        uint32_t ac[2],bc[2];bool negative[2];
                        for(unsigned item=0u;item<2u;++item) {
                            const unsigned i=pair*2u+item;
                            const int x=qrt_sm121_integer_core::signed_core(a.original[i],a.unit),y=qrt_sm121_integer_core::signed_core(b.original[i],b.unit);
                            mathematical+=int64_t(x)*y;ac[item]=unsigned(x<0?-x:x);bc[item]=unsigned(y<0?-y:y);negative[item]=((a.original[i]^b.original[i])&0x8000u)!=0u;
                        }
                        const uint32_t low=(ac[0]*bc[0])&65535u,high=(ac[1]*bc[1])&65535u;
                        const uint32_t packed_product=low|(high<<16u);
                        for(unsigned item=0u;item<2u;++item) {
                            const unsigned i=pair*2u+item,r=(packed_product>>(item*16u))&mask;
                            remainder+=negative[item]?-int64_t(r):int64_t(r);
                            if(exceptional&(1u<<i)) {
                                const unsigned original_shift=unsigned(maximum-terms[i+1u].exponent);
                                const unsigned original=original_shift>=32u?0u:(terms[i+1u].significand<<2u)>>original_shift;
                                const uint64_t core=uint64_t(ac[item])*bc[item];
                                const int64_t aligned=shift<=0?int64_t(core<<(-shift)):int64_t(core>>shift);
                                const int64_t delta=int64_t(original)-aligned;corrections+=negative[item]?-delta:delta;
                            }
                        }
                    }
                    const int64_t compensated=mathematical-remainder;
                    assert(shift<=0||compensated%int64_t(1u<<shift)==0);
                    int64_t candidate=shift<=0?compensated*(int64_t(1)<<(-shift)):compensated/int64_t(1u<<shift);
                    candidate+=corrections;
                    const unsigned carry_shift=unsigned(maximum-carry.exponent),aligned=carry_shift>=32u?0u:(carry.significand<<2u)>>carry_shift;
                    candidate+=carry.negative?-int64_t(aligned):int64_t(aligned);
                    for(const auto& term:terms){const unsigned s=unsigned(maximum-term.exponent);const uint64_t x=s>=32u?0u:(uint64_t(term.significand)<<2u)>>s;reference+=term.negative?-int64_t(x):int64_t(x);}
                    bounds_mismatches+=candidate!=reference;
                }
            }
            carry=qrt_q1_moe_hawkeye::group_sum<26,-133>(terms,17u);
        }
        if(sample%1024u==0u) {
            const float actual=qrt_q1_moe_hawkeye::value_to_float(qrt_q1_moe_hawkeye::group_sum<26,-133>(&carry,1u));
            assert(bits(actual)==bits(qrt_q1_moe_hawkeye::accumulate_bf16_hopper_blackwell(0.0f,qrow,krow,256u)));
        }
    }
    assert(groups==1048576u&&bounds_mismatches==0u);
    std::printf("{\"sampled_complete_dots\":65536,\"groups\":%llu,\"unsupported_rows\":%llu,\"packed_low16_supported_groups\":%llu,\"exact_aligned_sum_mismatches\":%llu,\"loss_pairs\":%llu,\"exception_pairs\":%llu,\"zero_correction_groups\":%llu,\"shift_histogram\":{",groups,unsupported,packed,bounds_mismatches,loss_pairs,exception_pairs,no_correction);
    bool comma=false;for(unsigned i=0u;i<97u;++i)if(shift_hist[i]){std::printf("%s\"%d\":%llu",comma?",":"",int(i)-32,shift_hist[i]);comma=true;}
    std::printf("},\"exception_pair_histogram\":[");for(unsigned i=0u;i<17u;++i)std::printf("%s%llu",i?",":"",exceptions[i]);
    std::puts("],\"gpu_counters\":false,\"inference_acceptance\":false,\"performance_acceptance\":false}");
}
